"""Publish a furnished plan directly from the same registry used by the game."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'src/layout-v11.json').read_text(encoding='utf-8'))
out=ROOT/'arte/casona-v12';out.mkdir(parents=True,exist_ok=True)
template=r'''<!doctype html>
<html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Croquis amueblado · Noche de Ánimas</title>
<style>*{box-sizing:border-box}body{margin:0;background:#e9e1d3;color:#292a28;font:16px/1.55 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:32px;line-height:1.2;margin:8px 0 16px}h2{font-size:23px}a{color:#6b2030}nav,.controls,.legend{display:flex;gap:12px;flex-wrap:wrap;align-items:center}nav{margin:16px 0}button,select{font:inherit;padding:9px 12px;border:1px solid #827760;background:#fffaf1;color:#292a28;border-radius:4px}button[aria-pressed=true]{background:#6b2030;color:#fffaf1}.controls{margin-bottom:16px}.layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:24px}.map{background:#f8f4e9;border:1px solid #b4a48a;border-radius:6px;overflow:hidden}svg{width:100%;display:block;aspect-ratio:62/43}svg text{font-family:system-ui;pointer-events:none}svg .room{cursor:pointer}svg .room:hover{fill:#e3ccb4}ul{padding-left:20px}li{margin-bottom:12px}.muted{color:#635c50}.legend{font-size:14px;margin:12px 0}.key{display:inline-block;width:14px;height:14px;margin-right:5px;vertical-align:middle}.item{padding:12px 0;border-bottom:1px solid #c7baa4}.item p{margin:4px 0}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin:28px 0}.gallery figure{margin:0}.gallery img{width:100%;border-radius:4px;display:block}.gallery figcaption{padding:8px 0}details{margin:20px 0}#selection{max-height:700px;overflow:auto;padding-right:8px}@media(max-width:800px){main{padding:16px}.layout{grid-template-columns:1fr}#selection{max-height:none}h1{font-size:27px}}</style>
<main><p class="muted">NOCHE DE ÁNIMAS · DISTRIBUCIÓN V12.1</p><h1>Croquis amueblado de la casona</h1><p>Selecciona un cuarto para acercarte y revisar cada mueble, su altura y su contenido previsto. Las posiciones coinciden con las del juego.</p>
<nav><a href="../../juego/?v=casona-v12">Jugar</a><a href="../../src/layout-v11.json">Registro de posiciones</a><a href="https://github.com/Jonathan-Bello/Noche-de-animas-3D/blob/main/docs/casona-v12.md">Cambios y pruebas</a></nav>
<div class="controls"><button id="pb" aria-pressed="true">Planta baja</button><button id="pa" aria-pressed="false">Planta alta</button><select id="rooms" aria-label="Seleccionar cuarto"></select><button id="general">Vista general</button><button id="base">Base y camioneta</button></div>
<div class="legend"><span><i class="key" style="background:#c4a17b"></i>Mueble fijo</span><span><i class="key" style="background:#6b2030"></i>Refugio candidato</span><span><i class="key" style="background:#a2bcaa"></i>Circulación</span><span><i class="key" style="background:#64829a"></i>Ventana</span></div>
<div class="layout"><div class="map"><svg id="plan" viewBox="-1 -1 62 43" role="img" aria-label="Plano amueblado de ambas plantas"></svg></div><aside id="selection" aria-live="polite"></aside></div>
<details><summary>Criterios del mobiliario y los escondites</summary><ul><li>Veinticuatro muebles de refugio en posiciones fijas; 21–22 disponibles en las noches ensayadas. Se sortean candados y disponibilidad, no la posición del mueble.</li><li>Máximo de 18 m de camino horizontal hasta un refugio, con puertas transitables. No supone inmunidad ni garantiza escapar durante una cacería.</li><li>Uniones, entradas, descansos y desembarcos de las escaleras libres de mesas. Los arcones del vestíbulo quedan fuera de la trayectoria de subida.</li><li>La biblioteca tiene 24 libros independientes en cuatro niveles del librero. El ánima los puede arrojar; al salir del estante no queda una copia decorativa.</li><li>Las listas describen el contenido previsto. Suministros, altar ritual, fusibles y hogar siguen variando entre partidas.</li></ul></details>
<h2>Aspecto en el juego</h2><p class="muted">Capturas con luces encendidas para inspeccionar los modelos.</p><div class="gallery">__GALLERY__</div><p class="muted">Las pruebas de pantalla móvil son emuladas. El rendimiento en un celular físico sigue pendiente de medir.</p></main>
<script>
const D=__DATA__,svg=document.getElementById('plan'),select=document.getElementById('rooms'),panel=document.getElementById('selection');let floor=0,current=null;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;'),rect=(r,fill,extra='')=>`<rect x="${r[0]}" y="${r[1]}" width="${r[2]-r[0]}" height="${r[3]-r[1]}" fill="${fill}" ${extra}/>`;
const furniture=D.obstacles.filter(o=>!o.id.startsWith('reserva_')&&!o.id.startsWith('columna')&&o.id!=='figura_central_fuente').map((o,k)=>({...o,code:'M'+String(k+1).padStart(2,'0')}));
const names={fuente:'Fuente del patio',altar_fijo:'Retablo y mesa de la capilla',prop_mecedora:'Mecedora',prop_caballito:'Caballito infantil',prop_cuna:'Cuna',prop_reloj:'Reloj de pie',prop_grifo_traspatio:'Lavadero de patio',prop_grifo_cocina:'Fregadero de cocina',prop_grifo_banoalto:'Lavabo',piano:'Piano',banera:'Bañera'};
function roomOf(o){return o.room||D.rooms.find(r=>r.floor===o.floor&&(o.rect[0]+o.rect[2])/2>=r.rect[0]&&(o.rect[0]+o.rect[2])/2<r.rect[2]&&(o.rect[1]+o.rect[3])/2>=r.rect[1]&&(o.rect[1]+o.rect[3])/2<r.rect[3])?.id;}
function draw(){const rooms=D.rooms.filter(r=>r.floor===floor);select.innerHTML='<option value="">Todos los cuartos</option>'+rooms.map(r=>`<option value="${r.id}">${r.id} · ${esc(r.name)}</option>`).join('');select.value=current||'';document.getElementById('pb').setAttribute('aria-pressed',floor===0);document.getElementById('pa').setAttribute('aria-pressed',floor===1);
 let s=rect([0,0,60,40],'#544d43')+rect(D.ringOuter,'#a2bcaa')+rect(D.patio,floor?'#e6e0d4':'#c3c7b5');
 for(const r of rooms){s+=rect(r.rect,current===r.id?'#f3d7b7':'#f5efdf',`class="room" data-room="${r.id}"`);s+=`<text x="${r.rect[0]+.3}" y="${r.rect[1]+.85}" font-size=".65" fill="#40392f">${r.id} · ${esc(r.name)}</text>`;}
 for(const d of D.doors.filter(d=>d.floor===floor)){s+=rect(d.rect,'#f5efdf');const[a,z,c,e]=d.rect;s+=`<path d="${c-a===1?`M${a+.15},${z}v2`:`M${a},${z+.15}h2`}" stroke="#8f5f3e" stroke-width=".12"/>`;}
 for(const w of D.windows.filter(w=>w.floor===floor)){s+=`<path d="M${w.start[0]},${w.start[1]} L${w.end[0]},${w.end[1]}" stroke="#64829a" stroke-width=".3"><title>${esc(w.state)}</title></path>`;}
 for(const stair of D.stairs){s+=rect(stair.hole,'#aab3ae',`stroke="#4d6558" stroke-width=".08"`);s+=`<polyline points="${stair.path.map(p=>p[0]+','+p[1]).join(' ')}" fill="none" stroke="#354d42" stroke-width=".16"/><text x="${stair.hole[0]+.2}" y="${stair.hole[1]+.7}" font-size=".55">${stair.id==='principal'?'Escalera U':'Servicio'} ↑</text>`;}
 for(const o of furniture.filter(o=>o.floor===floor)){const[a,z,c,e]=o.rect,label=o.label||names[o.id]||o.id;s+=rect(o.rect,'#c4a17b',`stroke="#79563d" stroke-width=".05" data-room="${roomOf(o)||''}" class="room"`)+`<text x="${(a+c)/2}" y="${(z+e)/2+.18}" text-anchor="middle" font-size=".47">${o.code}</text>`;}
 for(const h of D.hidingSockets.filter(h=>h.floor===floor)){const[x,z]=h.preferredSolid;s+=rect([x,z,x+1,z+1],'#6b2030',`data-room="${h.room}" class="room"`)+`<text x="${x+.5}" y="${z+.62}" text-anchor="middle" font-size=".32" fill="#fff6e2">${h.id}</text><path d="M${h.x+.5},${h.z+.5}L${x+.5},${z+.5}" stroke="#6b2030" stroke-width=".10"/><circle cx="${h.x+.5}" cy="${h.z+.5}" r=".15" fill="#6b2030"/>`;}
 if(!floor){s+=rect([0,40,60,59],'#d0cfbd')+rect(D.exterior.path,'#a2bcaa')+rect(D.exterior.apron,'#bbc9bb')+rect(D.exterior.van.collision,'#887d72')+`<text x="${D.exterior.van.position[0]}" y="${D.exterior.van.position[1]+.3}" text-anchor="middle" font-size=".7">Camioneta</text>`;for(const r of[[14,51,20,52],[14,55,20,56]])s+=rect(r,'#c4a17b');s+=`<text x="15" y="56.8" font-size=".65">Equipo y monitores</text>`;}
 svg.innerHTML=s;svg.querySelectorAll('[data-room]').forEach(e=>e.onclick=()=>choose(e.dataset.room));detail();}
function choose(id){current=id||null;const r=D.rooms.find(r=>r.id===current);if(r)floor=r.floor;draw();svg.setAttribute('viewBox',r?`${r.rect[0]-1.3} ${r.rect[1]-1.3} ${r.rect[2]-r.rect[0]+2.6} ${r.rect[3]-r.rect[1]+2.6}`:'-1 -1 62 43');}
function detail(){const r=D.rooms.find(r=>r.id===current);if(!r){panel.innerHTML='<h2>Distribución fija</h2><p>Selecciona un cuarto en el plano.</p><p>El circuito del patio conecta dos escaleras. La camioneta queda al este del camino; las mesas de equipo quedan libres al oeste.</p>';return;}const items=furniture.filter(o=>o.floor===floor&&roomOf(o)===r.id);panel.innerHTML=`<h2>${r.id} · ${esc(r.name)}</h2><p>${r.rect[2]-r.rect[0]} × ${r.rect[3]-r.rect[1]} m · ${r.home?'Cuarto elegible para hogar':'Zona de tránsito'}</p>`+items.map(o=>`<div class="item"><strong>${o.code} · ${esc(o.label||names[o.id]||o.id)}</strong><p>Huella reservada: ${o.rect[2]-o.rect[0]} × ${o.rect[3]-o.rect[1]} m · altura ${o.visualHeight||o.height} m</p><p class="muted">${esc((o.contents||[]).join(', ')||(o.kind==='prop'?'Objeto de ambiente que el ánima puede activar.':'Mobiliario fijo; no contiene suministros obligatorios.'))}</p></div>`).join('')+D.hidingSockets.filter(h=>h.room===r.id).map(h=>`<div class="item"><strong>${h.id} · ${esc(h.type)}</strong><p>Huella reservada: 1 × 1 m · altura ${/arcon|baul/.test(h.type)?1.05:h.type==='confesionario'?2.3:2} m.</p><p>Refugio fijo; acceso indicado por el punto y la línea.</p><p class="muted">${esc(h.contents)}</p></div>`).join('');}
document.getElementById('pb').onclick=()=>{floor=0;choose(null)};document.getElementById('pa').onclick=()=>{floor=1;choose(null)};document.getElementById('general').onclick=()=>choose(null);document.getElementById('base').onclick=()=>{floor=0;choose(null);svg.setAttribute('viewBox','10 39 35 20')};select.onchange=()=>choose(select.value);choose(new URLSearchParams(location.search).get('cuarto'));
</script></html>'''
gallery=''.join(f'<figure><a href="{name}.png"><img loading="lazy" src="{name}.png" alt="{label}"></a><figcaption>{label}</figcaption></figure>' for name,label in [('aperos','Cuarto de aperos: banco y materiales de mantenimiento'),('aperos_refugio','Arcón junto al muro este, fuera de las puertas'),('biblioteca','Librero abierto con libros independientes'),('comedor','Mesa, sillas y vajilla'),('base','Camioneta fuera del camino'),('zaguan','Arco y encuentro de muros'),('escalera_principal','Escalera principal'),('escalera_servicio','Acceso de servicio despejado')])
(out/'index.html').write_text(template.replace('__DATA__',json.dumps(d,ensure_ascii=False,separators=(',',':'))).replace('__GALLERY__',gallery),encoding='utf-8')
print(out/'index.html')
